      "filename": "sdk/serving.py",
      "language": "python",
      "description": "Real-time feature serving client using Redis for low-latency access",
      "code": "import redis
import json

class FeatureServingClient:
    def __init__(self, redis_url: str):
        self.redis = redis.Redis.from_url(redis_url)

    def get_features(self, entity_keys: list[str], feature_list: list[str]):
        results = {}
        for key in entity_keys:
            raw = self.redis.get(key)
            if not raw:
                continue
            data = json.loads(raw)
            results[key] = {f: data.get(f) for f in feature_list}
        return results"
    },
