      "filename": "api/routes/features.py",
      "language": "python",
      "description": "Feature registration, retrieval, and metadata endpoints",
      "code": "from fastapi import APIRouter
from pydantic import BaseModel
from sdk.registry import FeatureRegistry, FeatureDefinition

router = APIRouter(prefix='/api/features', tags=['features'])
registry = FeatureRegistry(feast_repo_path='./feast_repo')

class FeatureRequest(BaseModel):
    name: str
    owner: str
    version: str
    source_table: str
    description: str
    tags: list[str]

@router.post('/register')
def register_feature(req: FeatureRequest):
    feature_def = FeatureDefinition(**req.dict())
    response = registry.register_feature(feature_def)
    return response

@router.get('/{feature_name}')
def get_feature_metadata(feature_name: str):
    # Simulated lookup in Feast registry
    return {
        'feature_name': feature_name,
        'version': 'v1',
        'owner': 'ml_team',
        'metadata': {
            'description': 'Example feature metadata',
            'lineage': 'source_table:transactions',
            'tags': ['customer', 'rfm']
        }
    }"
    },
